// ── Funções ──────────────────────────────────────────────────
function norm(s) {
  return String(s).toUpperCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^A-Z0-9 ]/g, " ");
}

function isTESQuery(txt) {
  const t = norm(txt);
  const keywords = ["TES","NOVA TES","SUBSTITUIU","SUBSTITUI","CODIGO TES","CTE","CONHEC FRETE","CONHECIMENTO FRETE"];
  const hasKeyword = keywords.some(k => t.includes(k));
  const nums = txt.match(/\b\d{3}\b/g) || [];
  const hasNum = nums.some(n => {
    const v = parseInt(n);
    return (v >= 200 && v <= 279) || (v >= 350 && v <= 394);
  });
  return hasKeyword || hasNum;
}

function buscar(q) {
  const nums = q.match(/\b\d{3}\b/g) || [];
  for (const n of nums) {
    const c = parseInt(n);
    const porAntiga = REL.find(t => t.antiga === c);
    if (porAntiga) return [porAntiga];
    const porNova = REL.find(t => t.nova === c);
    if (porNova) return [porNova];
  }
  const palavras = norm(q).split(" ").filter(w => w.length > 2);
  if (!palavras.length) return [];
  return REL.filter(t => palavras.every(w => norm(t.desc).includes(w)));
}

function linha(...partes) {
  return partes.join("\n");
}

function montarResposta(resultados, textoOriginal) {
  const rodape = "\n─────────────────\n🌐 *Portal de consulta completa:*\nnovates.solucoesb4.com.br";
  let corpo = "";

  if (!resultados.length) {
    corpo = linha(
      "❌ *Nenhuma TES encontrada!*",
      "_Busca: " + textoOriginal + "_",
      "",
      "Tente o código (ex: *200*) ou palavras da descrição:",
      "• *TES 215*",
      "• *armazenagem interna*",
      "• *devolução compra*"
    );
  } else if (resultados.length === 1) {
    const r = resultados[0];
    corpo = linha(
      "✅ *TES Localizada!*",
      "",
      "🔁 *Código Antigo:* " + r.antiga,
      "✨ *Código Novo:*    " + r.nova,
      "📄 *Descrição:* " + r.desc.trim()
    );
  } else if (resultados.length <= 6) {
    const lista = resultados.map(r =>
      "• *" + r.antiga + "* → *" + r.nova + "*\n  _" + r.desc.trim().slice(0, 55) + "..._"
    ).join("\n\n");
    corpo = linha(
      "🔍 *" + resultados.length + " TES encontradas:*",
      "",
      lista,
      "",
      "_Use o código exato para mais detalhes._"
    );
  } else {
    corpo = linha(
      "⚠️ *Muitos resultados (" + resultados.length + ")*",
      "Seja mais específico.",
      "Ex: *armazenagem interna* em vez de *armazenagem*"
    );
  }

  return corpo + rodape;
}

// ── Execução ─────────────────────────────────────────────────
const ehTES = mensagem.length > 0 && isTESQuery(mensagem);
